pub fn shutdown(endpoint: u64) -> core::result::Result<(i32, VfsReplyStatus), InvokeError> {
    let wire_args = [0u8; 0];
    let mut wire_reply = [0u8; 8];
    let wire_len = 8;
    let wire_status = service::invoke(endpoint, 13, &wire_args, &[], &mut wire_reply[..wire_len])
        .map_err(InvokeError::Transport)?;
    let reply_status =
        decode_vfs_reply_status(&wire_reply[0..8]).map_err(|_| InvokeError::InvalidReply)?;
    Ok((wire_status, reply_status))
}
pub fn dispatch<P: Provider>(
    provider: &mut P,
    request: &service::Request<'_>,
    output: &mut [u8],
) -> i32 {
    let result = (|| -> Result<()> {
        validate(request)?;
        if output.len() != request.output {
            return Err(Errno::EINVAL);
        }
        match request.method {
            0 => {
                let wire_result = provider.root()?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                encode_vfs_path(&wire_result.token, &mut output[8..40])
                    .map_err(|_| Errno::EINVAL)?;
            }
            1 => {
                let options = decode_vfs_lookup(&request.args[0..80]).map_err(|_| Errno::EINVAL)?;
                let wire_result = provider.resolve(options, request.input)?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                encode_vfs_path(&wire_result.token, &mut output[8..40])
                    .map_err(|_| Errno::EINVAL)?;
            }
            2 => {
                let token = decode_vfs_path(&request.args[0..32]).map_err(|_| Errno::EINVAL)?;
                let wire_result = provider.node_info(token)?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                encode_vfs_node_info(&wire_result.info, &mut output[8..32])
                    .map_err(|_| Errno::EINVAL)?;
            }
            3 => {
                let token = decode_vfs_path(&request.args[0..32]).map_err(|_| Errno::EINVAL)?;
                let cursor =
                    u64::from_le_bytes(request.args[32..40].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.read_dir(token, cursor, &mut output[64..])?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                encode_vfs_dir_reply(&wire_result.directory, &mut output[8..64])
                    .map_err(|_| Errno::EINVAL)?;
            }
            4 => {
                let options =
                    decode_vfs_open_request(&request.args[0..48]).map_err(|_| Errno::EINVAL)?;
                let wire_result = provider.open(options, request.input)?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                output[8..16].copy_from_slice(&wire_result.file.to_le_bytes());
            }
            5 => {
                let file =
                    u64::from_le_bytes(request.args[0..8].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.retain(file)?;
                encode_vfs_reply_status(&wire_result, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
            }
            6 => {
                let file =
                    u64::from_le_bytes(request.args[0..8].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.read(file, &mut output[16..])?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                output[8..16].copy_from_slice(&wire_result.actual.to_le_bytes());
            }
            7 => {
                let file =
                    u64::from_le_bytes(request.args[0..8].try_into().map_err(|_| Errno::EINVAL)?);
                let offset =
                    u64::from_le_bytes(request.args[8..16].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.read_at(file, offset, &mut output[16..])?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                output[8..16].copy_from_slice(&wire_result.actual.to_le_bytes());
            }
            8 => {
                let file =
                    u64::from_le_bytes(request.args[0..8].try_into().map_err(|_| Errno::EINVAL)?);
                let offset =
                    u64::from_le_bytes(request.args[8..16].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.set_position(file, offset)?;
                encode_vfs_reply_status(&wire_result, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
            }
            9 => {
                let file =
                    u64::from_le_bytes(request.args[0..8].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.stream_info(file)?;
                encode_vfs_reply_status(&wire_result.reply_status, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
                encode_vfs_stream_info(&wire_result.info, &mut output[8..64])
                    .map_err(|_| Errno::EINVAL)?;
            }
            10 => {
                let file =
                    u64::from_le_bytes(request.args[0..8].try_into().map_err(|_| Errno::EINVAL)?);
                let wire_result = provider.close(file)?;
                encode_vfs_reply_status(&wire_result, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
            }
            11 => {
                let token = decode_vfs_path(&request.args[0..32]).map_err(|_| Errno::EINVAL)?;
                let wire_result = provider.retain_path(token)?;
                encode_vfs_reply_status(&wire_result, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
            }
            12 => {
                let token = decode_vfs_path(&request.args[0..32]).map_err(|_| Errno::EINVAL)?;
                let wire_result = provider.release_path(token)?;
                encode_vfs_reply_status(&wire_result, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
            }
            13 => {
                let wire_result = provider.shutdown()?;
                encode_vfs_reply_status(&wire_result, &mut output[0..8])
                    .map_err(|_| Errno::EINVAL)?;
            }
            _ => return Err(Errno::ENOSYS),
        }
        Ok(())
    })();
    match result {
        Ok(()) => 0,
        Err(error) => error.code(),
    }
}
